import 'package:flutter/material.dart';
import '../../core/constants/app_constants.dart';
import '../../core/theme/app_colors.dart';
import '../../models/hospital.dart';
import '../../models/mock_data.dart';
import '../../models/patient.dart';
import '../../services/assessment_service.dart';
import '../../services/hospital_matching_service.dart';
import '../../widgets/widgets.dart';
import '../../core/utils/navigation_utils.dart';

/// Screen displaying ranked hospital recommendations generated by the clinical matching engine.
/// Shows Best Match, Alternative options, capability checklists, transit times,
/// detailed score breakdowns, and unsuitable excluded facilities with explicit clinical reasons.
class HospitalRecommendationsScreen extends StatefulWidget {
  final Patient patient;
  final AssessmentResult assessment;
  final HospitalMatchingService matchingService;
  final List<Hospital>? hospitals;
  final double clinicLatitude;
  final double clinicLongitude;

  const HospitalRecommendationsScreen({
    super.key,
    required this.patient,
    required this.assessment,
    this.matchingService = const ClinicalHospitalMatchingService(),
    this.hospitals,
    this.clinicLatitude = 22.8100,
    this.clinicLongitude = 75.9200,
  });

  @override
  State<HospitalRecommendationsScreen> createState() =>
      _HospitalRecommendationsScreenState();
}

class _HospitalRecommendationsScreenState
    extends State<HospitalRecommendationsScreen> {
  late HospitalRecommendationResult _recommendations;
  bool _showScoreBreakdown = false;

  @override
  void initState() {
    super.initState();
    _evaluateRecommendations();
  }

  void _evaluateRecommendations() {
    final candidateHospitals =
        widget.hospitals ?? MockClinicalData.sampleHospitals;
    _recommendations = widget.matchingService.evaluateRecommendations(
      patient: widget.patient,
      assessment: widget.assessment,
      availableHospitals: candidateHospitals,
      clinicLatitude: widget.clinicLatitude,
      clinicLongitude: widget.clinicLongitude,
    );
  }

  void _onSelectHospital(Hospital hospital, String tier) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        backgroundColor: AppColors.primaryGreen,
        content: Text(
          '$tier selected: ${hospital.name}. Transfer dispatch logged.',
        ),
        duration: const Duration(seconds: 3),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final theme = Theme.of(context);
    final bestMatch = _recommendations.bestMatch;
    final alternatives = _recommendations.alternatives;
    final excluded = _recommendations.excludedHospitals;

    return Scaffold(
      backgroundColor: AppColors.backgroundLight,
      body: SafeArea(
        child: Column(
          children: [
            // App Header
            AppHeader(
              title: 'Hospital Recommendations',
              subtitle: 'Ranked Referral Destinations',
              leading: IconButton(
                icon: const Icon(Icons.arrow_back_rounded),
                onPressed: () => SafeNavigation.pop(context, fallbackTab: 1),
                tooltip: 'Return to Assessment Result',
              ),
              showClinicStatusBar: false,
            ),

            // Content Body
            Expanded(
              child: SingleChildScrollView(
                padding: const EdgeInsets.all(AppConstants.spacingMd),
                physics: const BouncingScrollPhysics(),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    // Referral Context Banner
                    _buildReferralSummaryBanner(theme),

                    const SizedBox(height: AppConstants.spacingLg),

                    // ==========================================
                    // 1. BEST MATCH SECTION
                    // ==========================================
                    if (bestMatch != null) ...[
                      const SectionHeader(
                        title: 'BEST MATCH',
                        subtitle: 'Top-ranked clinical destination meeting all mandatory criteria',
                      ),
                      _buildHospitalCard(
                        context,
                        match: bestMatch,
                        rankLabel: 'BEST MATCH',
                        isBestMatch: true,
                      ),
                    ] else ...[
                      // No suitable hospitals found state
                      _buildNoMatchesFoundCard(),
                    ],

                    const SizedBox(height: AppConstants.spacingLg),

                    // ==========================================
                    // 2. ALTERNATIVES SECTION
                    // ==========================================
                    if (alternatives.isNotEmpty) ...[
                      SectionHeader(
                        title: 'Alternative Referral Options',
                        subtitle: '${alternatives.length} additional facility eligible for this transfer',
                      ),
                      for (int i = 0; i < alternatives.length; i++) ...[
                        _buildHospitalCard(
                          context,
                          match: alternatives[i],
                          rankLabel: 'Alternative ${i + 1}',
                          isBestMatch: false,
                        ),
                        if (i < alternatives.length - 1)
                          const SizedBox(height: AppConstants.spacingMd),
                      ],
                      const SizedBox(height: AppConstants.spacingLg),
                    ],

                    // ==========================================
                    // 3. UNSUITABLE / EXCLUDED HOSPITALS SECTION
                    // ==========================================
                    if (excluded.isNotEmpty) ...[
                      SectionHeader(
                        title: 'Excluded Facilities (${excluded.length})',
                        subtitle: 'Facilities disqualified by mandatory capability hard filters',
                      ),
                      _buildExcludedHospitalsList(context, excluded),
                    ],

                    const SizedBox(height: AppConstants.spacingXl),

                    // Return Button
                    SecondaryButton(
                      text: 'Return to Assessment Review',
                      icon: Icons.assignment_outlined,
                      onPressed: () => SafeNavigation.pop(context, fallbackTab: 1),
                    ),

                    const SizedBox(height: AppConstants.spacingXxl),
                  ],
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildReferralSummaryBanner(ThemeData theme) {
    return Container(
      padding: const EdgeInsets.all(AppConstants.spacingMd),
      decoration: BoxDecoration(
        color: AppColors.surfaceLight,
        borderRadius: BorderRadius.circular(AppConstants.radiusMd),
        border: Border.all(color: AppColors.borderLight),
      ),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  'Patient: ${widget.patient.patientId}',
                  style: const TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w700,
                    color: AppColors.textNavyPrimary,
                  ),
                ),
                const SizedBox(height: 2),
                Text(
                  'Required: ${widget.assessment.requiredSpecialty}',
                  style: const TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w600,
                    color: AppColors.secondarySlateTeal,
                  ),
                ),
              ],
            ),
          ),
          UrgencyBadge(
            urgencyLevel: widget.assessment.urgencyLevel,
            isCompact: true,
          ),
        ],
      ),
    );
  }

  Widget _buildHospitalCard(
    BuildContext context, {
    required HospitalMatchResult match,
    required String rankLabel,
    required bool isBestMatch,
  }) {
    final hosp = match.hospital;
    final score = match.matchScore.round();

    return AppCard(
      accentColor: isBestMatch ? AppColors.primaryGreen : AppColors.secondarySlateTeal,
      padding: const EdgeInsets.all(AppConstants.spacingMd),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // Header Row: Rank pill + Score indicator
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                decoration: BoxDecoration(
                  color: isBestMatch
                      ? AppColors.primaryLightMint
                      : AppColors.surfaceMutedLight,
                  borderRadius: BorderRadius.circular(AppConstants.radiusSm),
                  border: Border.all(
                    color: isBestMatch
                        ? AppColors.primaryGreen
                        : AppColors.borderLight,
                  ),
                ),
                child: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Icon(
                      isBestMatch ? Icons.star_rounded : Icons.check_circle_outline,
                      size: 14,
                      color: isBestMatch
                          ? AppColors.primaryGreen
                          : AppColors.textNavySecondary,
                    ),
                    const SizedBox(width: 4),
                    Text(
                      rankLabel,
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w800,
                        color: isBestMatch
                            ? AppColors.primaryDarkGreen
                            : AppColors.textNavyPrimary,
                        letterSpacing: 0.2,
                      ),
                    ),
                  ],
                ),
              ),
              // Match Score Pill (e.g. 92/100)
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                decoration: BoxDecoration(
                  color: score >= 85
                      ? AppColors.statusGreenBg
                      : (score >= 70
                          ? AppColors.statusAmberBg
                          : AppColors.surfaceMutedLight),
                  borderRadius: BorderRadius.circular(AppConstants.radiusSm),
                  border: Border.all(
                    color: score >= 85
                        ? AppColors.statusGreen
                        : AppColors.statusAmber,
                  ),
                ),
                child: Text(
                  '$score/100',
                  style: TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.w800,
                    color: score >= 85
                        ? AppColors.primaryDarkGreen
                        : AppColors.textNavyPrimary,
                  ),
                ),
              ),
            ],
          ),

          const SizedBox(height: AppConstants.spacingSm),

          // Hospital Name & Address
          Text(
            hosp.name,
            style: const TextStyle(
              fontSize: 17,
              fontWeight: FontWeight.w800,
              color: AppColors.textNavyPrimary,
              letterSpacing: -0.2,
            ),
          ),
          const SizedBox(height: 2),
          Text(
            hosp.address,
            style: const TextStyle(
              fontSize: 12,
              color: AppColors.textNavyMuted,
            ),
          ),

          if (hosp.tags.isNotEmpty) ...[
            const SizedBox(height: 6),
            Wrap(
              spacing: 6,
              runSpacing: 4,
              children: hosp.tags.take(3).map((t) => _buildRecoTagPill(t)).toList(),
            ),
          ],

          const SizedBox(height: AppConstants.spacingMd),

          // Transit metrics row (Distance & Travel Time)
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),
            decoration: BoxDecoration(
              color: AppColors.surfaceMutedLight,
              borderRadius: BorderRadius.circular(AppConstants.radiusSm),
            ),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceAround,
              children: [
                Row(
                  children: [
                    const Icon(
                      Icons.near_me_outlined,
                      size: 16,
                      color: AppColors.secondarySlateTeal,
                    ),
                    const SizedBox(width: 6),
                    Text(
                      'Distance: ${match.distanceKm.toStringAsFixed(1)} km (~${(match.distanceKm * 1000).round()} m)',
                      style: const TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w600,
                        color: AppColors.textNavyPrimary,
                      ),
                    ),
                  ],
                ),
                Container(width: 1, height: 16, color: AppColors.borderLight),
                Row(
                  children: [
                    const Icon(
                      Icons.directions_car_rounded,
                      size: 16,
                      color: AppColors.secondarySlateTeal,
                    ),
                    const SizedBox(width: 6),
                    Text(
                      'Travel Time: ~${match.travelTime.inMinutes} mins by Car',
                      style: const TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w600,
                        color: AppColors.textNavyPrimary,
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),

          const SizedBox(height: AppConstants.spacingMd),

          // Capability Checkmarks (6 required checklist points)
          Text(
            'Clinical Capabilities Matched:',
            style: Theme.of(context).textTheme.titleSmall?.copyWith(
                  fontWeight: FontWeight.w700,
                  color: AppColors.textNavyPrimary,
                  fontSize: 12,
                ),
          ),
          const SizedBox(height: 8),

          _buildCheckmarkRow(
            label: 'Required Specialty: ${widget.assessment.requiredSpecialty}',
            isMet: match.hasRequiredSpecialty,
          ),
          _buildCheckmarkRow(
            label: '24/7 Emergency Care',
            isMet: match.hasEmergencyCapability,
          ),
          _buildCheckmarkRow(
            label: 'Intensive Care Unit (ICU)',
            isMet: match.hasIcu,
          ),
          _buildCheckmarkRow(
            label: 'Required Diagnostics (${hosp.diagnosticFacilities.take(3).join(", ")})',
            isMet: match.hasRequiredDiagnostics,
          ),
          _buildCheckmarkRow(
            label: 'Treatment Capability (${hosp.treatmentCapabilities.take(2).join(", ")})',
            isMet: match.hasRequiredTreatments,
          ),
          _buildCheckmarkRow(
            label: 'Simulated Availability (${hosp.bedAvailability} beds available • ${hosp.operatingStatus})',
            isMet: match.hasAvailableBeds,
          ),

          const SizedBox(height: AppConstants.spacingMd),

          // Score Breakdown Expandable Toggle
          InkWell(
            onTap: () {
              setState(() => _showScoreBreakdown = !_showScoreBreakdown);
            },
            borderRadius: BorderRadius.circular(AppConstants.radiusSm),
            child: Padding(
              padding: const EdgeInsets.symmetric(vertical: 4),
              child: Row(
                children: [
                  Icon(
                    _showScoreBreakdown
                        ? Icons.keyboard_arrow_up_rounded
                        : Icons.keyboard_arrow_down_rounded,
                    size: 18,
                    color: AppColors.secondarySlateTeal,
                  ),
                  const SizedBox(width: 4),
                  Text(
                    _showScoreBreakdown ? 'Hide Score Breakdown' : 'View Score Breakdown',
                    style: const TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w700,
                      color: AppColors.secondarySlateTeal,
                    ),
                  ),
                ],
              ),
            ),
          ),

          if (_showScoreBreakdown) ...[
            const SizedBox(height: 8),
            _buildScoreBreakdownTable(match.scoreBreakdown),
          ],

          const SizedBox(height: AppConstants.spacingMd),

          // Action Button
          PrimaryButton(
            text: isBestMatch ? 'Select Best Match' : 'Select This Alternative',
            icon: Icons.check_circle_outline,
            onPressed: () => _onSelectHospital(hosp, rankLabel),
          ),
        ],
      ),
    );
  }

  Widget _buildCheckmarkRow({
    required String label,
    required bool isMet,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 6),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Icon(
            isMet ? Icons.check_circle_rounded : Icons.cancel_rounded,
            size: 16,
            color: isMet ? AppColors.statusGreen : AppColors.statusRed,
          ),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              label,
              style: TextStyle(
                fontSize: 12,
                fontWeight: isMet ? FontWeight.w500 : FontWeight.w600,
                color: isMet ? AppColors.textNavyPrimary : AppColors.statusRed,
                height: 1.3,
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildScoreBreakdownTable(ScoreBreakdown breakdown) {
    return Container(
      padding: const EdgeInsets.all(AppConstants.spacingSm),
      decoration: BoxDecoration(
        color: AppColors.surfaceMutedLight,
        borderRadius: BorderRadius.circular(AppConstants.radiusSm),
        border: Border.all(color: AppColors.borderLight),
      ),
      child: Column(
        children: [
          _buildScoreBreakdownRow('Medical Capability (35%)', breakdown.medicalCapabilityScore, 35.0),
          _buildScoreBreakdownRow('Specialty Match (20%)', breakdown.specialtyMatchScore, 20.0),
          _buildScoreBreakdownRow('Emergency / ICU (15%)', breakdown.emergencyIcuScore, 15.0),
          _buildScoreBreakdownRow('Availability (15%)', breakdown.availabilityScore, 15.0),
          _buildScoreBreakdownRow('Travel Time (10%)', breakdown.travelTimeScore, 10.0),
          _buildScoreBreakdownRow('Distance (5%)', breakdown.distanceScore, 5.0),
          const Divider(height: 12),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              const Text(
                'Total Suitability Score',
                style: TextStyle(fontSize: 12, fontWeight: FontWeight.w800, color: AppColors.textNavyPrimary),
              ),
              Text(
                '${breakdown.totalScore.toStringAsFixed(1)} / 100',
                style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w800, color: AppColors.primaryDarkGreen),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildScoreBreakdownRow(String label, double score, double max) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 2),
      child: Row(
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          Text(label, style: const TextStyle(fontSize: 11, color: AppColors.textNavySecondary)),
          Text('${score.toStringAsFixed(1)} / ${max.toStringAsFixed(0)}',
              style: const TextStyle(fontSize: 11, fontWeight: FontWeight.w600, color: AppColors.textNavyPrimary)),
        ],
      ),
    );
  }

  Widget _buildNoMatchesFoundCard() {
    return Container(
      padding: const EdgeInsets.all(AppConstants.spacingLg),
      decoration: BoxDecoration(
        color: const Color(0xFFFEF2F2), // Soft red
        borderRadius: BorderRadius.circular(AppConstants.radiusMd),
        border: Border.all(color: AppColors.statusRed.withValues(alpha: 0.3)),
      ),
      child: Column(
        children: [
          const Icon(Icons.warning_amber_rounded, size: 36, color: AppColors.statusRed),
          const SizedBox(height: 8),
          const Text(
            'No Suitable Partner Hospitals Found',
            style: TextStyle(fontSize: 16, fontWeight: FontWeight.w800, color: AppColors.statusRed),
            textAlign: TextAlign.center,
          ),
          const SizedBox(height: 4),
          const Text(
            'All evaluated facilities in the simulated network were disqualified by mandatory capability hard filters (diverting status, zero bed capacity, or missing required specialty/ICU).',
            style: TextStyle(fontSize: 12, color: Color(0xFF991B1B), height: 1.4),
            textAlign: TextAlign.center,
          ),
        ],
      ),
    );
  }

  Widget _buildExcludedHospitalsList(
    BuildContext context,
    List<UnsuitableHospitalResult> excluded,
  ) {
    return Column(
      children: excluded.map((unsuitable) {
        final hosp = unsuitable.hospital;
        return Padding(
          padding: const EdgeInsets.only(bottom: AppConstants.spacingSm),
          child: Container(
            padding: const EdgeInsets.all(AppConstants.spacingMd),
            decoration: BoxDecoration(
              color: AppColors.surfaceLight,
              borderRadius: BorderRadius.circular(AppConstants.radiusMd),
              border: Border.all(color: AppColors.borderLight),
            ),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Expanded(
                      child: Text(
                        hosp.name,
                        style: const TextStyle(
                          fontSize: 14,
                          fontWeight: FontWeight.w700,
                          color: AppColors.textNavyPrimary,
                        ),
                      ),
                    ),
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                      decoration: BoxDecoration(
                        color: AppColors.statusRedBg,
                        borderRadius: BorderRadius.circular(AppConstants.radiusSm),
                        border: Border.all(color: AppColors.statusRed.withValues(alpha: 0.3)),
                      ),
                      child: const Text(
                        'Excluded',
                        style: TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w700,
                          color: AppColors.statusRed,
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 4),
                Text(
                  '${unsuitable.distanceKm.toStringAsFixed(1)} km (~${(unsuitable.distanceKm * 1000).round()} m) away • ~${unsuitable.travelTime.inMinutes} mins by Car',
                  style: const TextStyle(fontSize: 11, color: AppColors.textNavyMuted),
                ),
                const SizedBox(height: 6),
                const Divider(height: 8),
                const SizedBox(height: 4),
                ...unsuitable.exclusionReasons.map(
                  (reason) => Padding(
                    padding: const EdgeInsets.only(bottom: 2),
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Icon(
                          Icons.cancel_outlined,
                          size: 14,
                          color: AppColors.statusRed,
                        ),
                        const SizedBox(width: 6),
                        Expanded(
                          child: Text(
                            reason,
                            style: const TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.w600,
                              color: AppColors.statusRed,
                              height: 1.3,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      }).toList(),
    );
  }

  Widget _buildRecoTagPill(String tag) {
    Color bg;
    Color border;
    Color text;

    final lower = tag.toLowerCase();
    if (lower.contains('super speciality') || lower.contains('apex') || lower.contains('medical college')) {
      bg = const Color(0xFFEDE9FE);
      border = const Color(0xFFC4B5FD);
      text = const Color(0xFF5B21B6);
    } else if (lower.contains('government') || lower.contains('chc') || lower.contains('phc')) {
      bg = const Color(0xFFE0F2FE);
      border = const Color(0xFF7DD3FC);
      text = const Color(0xFF0369A1);
    } else if (lower.contains('emergency') || lower.contains('trauma') || lower.contains('cardiac')) {
      bg = const Color(0xFFFEE2E2);
      border = const Color(0xFFFCA5A5);
      text = const Color(0xFFB91C1C);
    } else if (lower.contains('icu') || lower.contains('blood bank')) {
      bg = const Color(0xFFFEF3C7);
      border = const Color(0xFFFCD34D);
      text = const Color(0xFFB45309);
    } else {
      bg = const Color(0xFFF1F5F9);
      border = const Color(0xFFCBD5E1);
      text = const Color(0xFF334155);
    }

    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 6.5, vertical: 2),
      decoration: BoxDecoration(
        color: bg,
        borderRadius: BorderRadius.circular(4),
        border: Border.all(color: border, width: 0.8),
      ),
      child: Text(
        tag,
        style: TextStyle(
          fontSize: 10,
          fontWeight: FontWeight.w700,
          color: text,
          letterSpacing: 0.2,
        ),
      ),
    );
  }
}
